create table social_references(id serial primary key,tenant_id int not null default nullif(current_setting('app.tenant',true),'')::int references tenants,name text not null,kind text not null check(kind in ('image','url')),image_data text,url text,notes text not null default '',created_at timestamptz not null default now());
create table editorial_plans(id serial primary key,tenant_id int not null default nullif(current_setting('app.tenant',true),'')::int references tenants,name text not null,brief text not null,channel_ids int[] not null,time_zone text not null,slots jsonb not null,reference_ids int[] not null default '{}',research boolean not null default true,auto_publish boolean not null default false,active boolean not null default false,created_by int references users,created_at timestamptz not null default now());
create table creative_jobs(id serial primary key,tenant_id int not null default nullif(current_setting('app.tenant',true),'')::int references tenants,plan_id int references editorial_plans,publication_id int references social_publications,brief text not null,format text not null check(format in ('flyer','carousel','video')),channel_ids int[] not null,reference_ids int[] not null default '{}',time_zone text not null,schedule_at timestamptz,research boolean not null default true,auto_publish boolean not null default false,status text not null default 'queued',phase text not null default 'research',sources jsonb not null default '[]',copy jsonb,media jsonb not null default '[]',remote_video_id text,error text,created_by int references users,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(tenant_id,plan_id,schedule_at));
alter table social_publications add column creative_job_id int references creative_jobs;
do $$declare t text;begin foreach t in array array['social_references','editorial_plans','creative_jobs'] loop execute format('alter table %I enable row level security',t);execute format('alter table %I force row level security',t);execute format('create policy tenant_iso on %I using(tenant_id=nullif(current_setting(''app.tenant'',true),'''')::int) with check(tenant_id=nullif(current_setting(''app.tenant'',true),'''')::int)',t);end loop;end $$;
create trigger fk_guard before insert or update on editorial_plans for each row execute function fk_guard('users','created_by');
create trigger fk_guard before insert or update on creative_jobs for each row execute function fk_guard('editorial_plans','plan_id','social_publications','publication_id','users','created_by');
create trigger creative_guard before insert or update on social_publications for each row execute function fk_guard('creative_jobs','creative_job_id');
create index creative_queue on creative_jobs(tenant_id,status,created_at);
create unique index social_creative_once on social_publications(creative_job_id) where creative_job_id is not null;
